--   audit_events.correlationId/requestId/entityId, workflow_instances.entityId,
--   rebac_edges.objectId/subjectUserId, refunds.originalOrId (receipt no.),
--   notification_logs.providerMsgId (external), messages.threadId (grouping key),
--   channel_configs.senderId (external)
